-- Phase 39: procurement intelligence extends the canonical Phase 16 purchasing flow.
-- Recommendations are advisory; no purchase, transfer, approval, send or payment is automatic.
create schema if not exists procurement_private;
revoke all on schema procurement_private from public,anon;
grant usage on schema procurement_private to authenticated,service_role;

alter table public.plans add column if not exists procurement_intelligence_enabled boolean not null default false;
alter table public.plans add column if not exists replenishment_planning_enabled boolean not null default false;
alter table public.plans add column if not exists supplier_scoring_enabled boolean not null default false;
alter table public.plans add column if not exists quote_comparison_enabled boolean not null default false;
alter table public.plans add column if not exists procurement_copilot_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists procurement_intelligence_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists replenishment_planning_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists supplier_scoring_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists quote_comparison_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists procurement_copilot_enabled boolean not null default true;

alter table public.inventory_items add column if not exists reserved_quantity numeric(18,4) not null default 0 check(reserved_quantity>=0);
alter table public.inventory_items add column if not exists shelf_life_days integer check(shelf_life_days is null or shelf_life_days>0);
alter table public.inventory_items add column if not exists procurement_category text;
alter table public.supplier_inventory_items add column if not exists minimum_order_quantity numeric(18,4) not null default 0 check(minimum_order_quantity>=0);
alter table public.supplier_inventory_items add column if not exists pack_size numeric(18,4) not null default 1 check(pack_size>0);
alter table public.supplier_inventory_items add column if not exists freight_cents bigint not null default 0 check(freight_cents>=0);
alter table public.supplier_inventory_items add column if not exists contracted_price_cents bigint check(contracted_price_cents is null or contracted_price_cents>=0);
alter table public.supplier_inventory_items add column if not exists contract_valid_from date;
alter table public.supplier_inventory_items add column if not exists contract_valid_to date;
alter table public.supplier_inventory_items add column if not exists max_adjustment_percent numeric(7,3);
alter table public.purchase_orders add column if not exists promised_delivery_date date;
alter table public.purchase_orders add column if not exists actual_delivery_date date;
alter table public.purchase_orders add column if not exists approval_status text not null default 'not_required' check(approval_status in('not_required','pending','approved','rejected'));
alter table public.purchase_orders add column if not exists second_approved_by uuid references auth.users(id) on delete set null;
alter table public.purchase_orders add column if not exists sent_at timestamptz;
alter table public.purchase_orders add column if not exists financial_commitment_id uuid references public.financial_entries(id) on delete set null;
alter table public.purchase_receipts add column if not exists invoice_total_cents bigint check(invoice_total_cents is null or invoice_total_cents>=0);
alter table public.purchase_receipts add column if not exists match_status text not null default 'missing_invoice' check(match_status in('matched','quantity_variance','price_variance','missing_invoice','unmatched'));
alter table public.purchase_receipt_items add column if not exists quality_status text not null default 'accepted' check(quality_status in('accepted','partial','rejected','not_applicable'));
alter table public.purchase_receipt_items add column if not exists damage_quantity numeric(18,4) not null default 0 check(damage_quantity>=0);
alter table public.purchase_receipt_items add column if not exists temperature_celsius numeric(7,2);
alter table public.purchase_receipt_items add column if not exists quality_notes text;

create table public.procurement_settings(organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,reorder_method text not null default 'lead_time_plus_safety' check(reorder_method in('lead_time_plus_safety','min_max','manual_override')),safety_stock_mode text not null default 'fixed' check(safety_stock_mode in('fixed','days_of_coverage','statistical_future')),safety_stock_days numeric(8,2) not null default 2 check(safety_stock_days>=0),approval_threshold_cents bigint not null default 0 check(approval_threshold_cents>=0),dual_approval_threshold_cents bigint,price_tolerance_percent numeric(8,3) not null default 2 check(price_tolerance_percent>=0),quantity_tolerance_percent numeric(8,3) not null default 2 check(quantity_tolerance_percent>=0),score_weights jsonb not null default '{"price":25,"lead_time":20,"on_time":25,"fill_rate":15,"quality":15}',updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now(),unique(organization_id,store_id));
create table public.procurement_recommendations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,warehouse_id uuid,inventory_item_id uuid not null references public.inventory_items(id) on delete cascade,supplier_id uuid references public.suppliers(id) on delete set null,recommended_qty numeric(18,4) not null check(recommended_qty>=0),recommended_date timestamptz not null,reason text not null,current_stock numeric(18,4) not null default 0,reserved_stock numeric(18,4) not null default 0,inbound_stock numeric(18,4) not null default 0,projected_consumption numeric(18,4) not null default 0,safety_stock numeric(18,4) not null default 0,reorder_point numeric(18,4) not null default 0,coverage_days numeric(12,2),stockout_at timestamptz,stockout_risk text not null check(stockout_risk in('low','medium','high','critical')),excess_risk text not null default 'low' check(excess_risk in('low','medium','high')),estimated_cost_cents bigint not null default 0,confidence text not null check(confidence in('high','medium','low')),evidence jsonb not null default '{}',priority text not null default 'normal' check(priority in('critical','high','normal','optional')),status text not null default 'suggested' check(status in('suggested','reviewed','accepted','dismissed','converted_to_purchase_order','expired')),purchase_order_id uuid references public.purchase_orders(id) on delete set null,reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.supplier_price_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete cascade,source_type text not null check(source_type in('quote','purchase_order','receipt','contract','manual')),source_id uuid,unit_price_cents numeric(18,4) not null check(unit_price_cents>=0),purchase_unit text not null,sampled_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null);
create table public.supplier_quotes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete cascade,rfq_id uuid,price_cents numeric(18,4) not null check(price_cents>=0),quantity numeric(18,4) not null check(quantity>0),unit text not null,valid_until date,freight_cents bigint not null default 0 check(freight_cents>=0),lead_time_days integer check(lead_time_days is null or lead_time_days>=0),minimum_order_quantity numeric(18,4) not null default 0,notes text,source text not null default 'manual' check(source in('manual','upload','integration','supplier_portal_future')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.procurement_rfqs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,items jsonb not null check(jsonb_typeof(items)='array'),due_date date not null,status text not null default 'draft' check(status in('draft','sent','partially_received','completed','cancelled')),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.supplier_quotes add constraint supplier_quotes_rfq_fkey foreign key(rfq_id) references public.procurement_rfqs(id) on delete set null;
create table public.supplier_receiving_issues(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,purchase_order_id uuid not null references public.purchase_orders(id) on delete cascade,receipt_id uuid references public.purchase_receipts(id) on delete set null,supplier_id uuid not null references public.suppliers(id) on delete cascade,item_id uuid references public.inventory_items(id) on delete set null,issue_type text not null check(issue_type in('short_delivery','excess_delivery','damaged','quality','late','price_mismatch','invoice_mismatch','wrong_item')),quantity numeric(18,4),amount_cents bigint,notes text,status text not null default 'open' check(status in('open','acknowledged','resolved','dismissed')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.procurement_budgets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,category text not null,month date not null check(date_trunc('month',month)::date=month),amount_cents bigint not null check(amount_cents>=0),alert_percent numeric(7,2) not null default 90 check(alert_percent between 0 and 100),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(organization_id,store_id,category,month));
create table public.supplier_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete cascade,document_type text not null check(document_type in('price_list','contract','certificate','invoice','other')),storage_path text not null,file_name text not null,sensitive boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(supplier_id,storage_path));
create table public.procurement_alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,alert_key text not null,alert_type text not null,severity text not null check(severity in('info','warning','high','critical')),message text not null,evidence jsonb not null default '{}',status text not null default 'open' check(status in('open','acknowledged','resolved')),first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),occurrences integer not null default 1,unique(organization_id,store_id,alert_key,status));
create table public.procurement_audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index procurement_recommendations_scope_idx on public.procurement_recommendations(organization_id,store_id,status,recommended_date);
create index supplier_price_history_lookup_idx on public.supplier_price_history(organization_id,inventory_item_id,supplier_id,sampled_at desc);
create index supplier_quotes_compare_idx on public.supplier_quotes(organization_id,inventory_item_id,valid_until,created_at desc);
create index receiving_issues_scope_idx on public.supplier_receiving_issues(organization_id,store_id,supplier_id,status,created_at desc);
create index procurement_audit_scope_idx on public.procurement_audit_events(organization_id,store_id,created_at desc);

create or replace function procurement_private.can_access(target_org uuid,target_store uuid,requested_permission text default 'procurement:view') returns boolean language sql stable security definer set search_path=''
as $$ select (select auth.uid()) is not null and (private.is_superadmin() or exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=(select auth.uid()) and m.active and m.role in('owner','admin') and(target_store is null or m.all_stores or exists(select 1 from public.organization_member_store_access a where a.organization_id=target_org and a.user_id=m.user_id and a.establishment_id=target_store))) or exists(select 1 from public.establishment_members em join public.establishments e on e.id=em.establishment_id where em.user_id=(select auth.uid()) and em.status='active' and e.organization_id=target_org and(target_store is null or em.establishment_id=target_store) and em.role in('owner','manager'))) $$;
revoke all on function procurement_private.can_access(uuid,uuid,text) from public,anon;
grant execute on function procurement_private.can_access(uuid,uuid,text) to authenticated;
do $$ declare t text; begin foreach t in array array['procurement_settings','procurement_recommendations','supplier_price_history','supplier_quotes','procurement_rfqs','supplier_receiving_issues','procurement_budgets','supplier_documents','procurement_alerts','procurement_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
create policy procurement_settings_read on public.procurement_settings for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy procurement_recommendations_read on public.procurement_recommendations for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy supplier_price_history_read on public.supplier_price_history for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy supplier_quotes_read on public.supplier_quotes for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy procurement_rfqs_read on public.procurement_rfqs for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy supplier_receiving_issues_read on public.supplier_receiving_issues for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy procurement_budgets_read on public.procurement_budgets for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy supplier_documents_read on public.supplier_documents for select to authenticated using(procurement_private.can_access(organization_id,null));
create policy procurement_alerts_read on public.procurement_alerts for select to authenticated using(procurement_private.can_access(organization_id,store_id));
create policy procurement_audit_events_read on public.procurement_audit_events for select to authenticated using(procurement_private.can_access(organization_id,store_id));
grant select on public.procurement_settings,public.procurement_recommendations,public.supplier_price_history,public.supplier_quotes,public.procurement_rfqs,public.supplier_receiving_issues,public.procurement_budgets,public.supplier_documents,public.procurement_alerts,public.procurement_audit_events to authenticated;

create table public.analytics_dim_suppliers(supplier_id uuid not null,organization_id uuid not null,name text not null,status text not null,effective_from timestamptz not null,effective_to timestamptz,is_current boolean not null default true,loaded_at timestamptz not null default now(),primary key(supplier_id,effective_from));
create table public.analytics_dim_procurement_categories(category_key text not null,organization_id uuid not null,name text not null,loaded_at timestamptz not null default now(),primary key(organization_id,category_key));
create table public.analytics_fact_purchase_orders(purchase_order_id uuid primary key,organization_id uuid not null,store_id uuid not null,supplier_id uuid not null,date_key integer references public.analytics_dim_date(date_key),status text not null,total_cents bigint not null,promised_delivery_date date,actual_delivery_date date,source_updated_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.analytics_fact_purchase_items(purchase_order_item_id uuid primary key,purchase_order_id uuid not null,organization_id uuid not null,store_id uuid not null,inventory_item_id uuid not null,quantity numeric not null,received_quantity numeric not null,unit_cost_cents numeric not null,total_cost_cents bigint not null,loaded_at timestamptz not null default now());
create table public.analytics_fact_supplier_quotes(quote_id uuid primary key,organization_id uuid not null,store_id uuid,supplier_id uuid not null,inventory_item_id uuid not null,price_cents numeric not null,freight_cents bigint not null,lead_time_days integer,valid_until date,created_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.analytics_fact_receivings(receipt_id uuid primary key,purchase_order_id uuid not null,organization_id uuid not null,store_id uuid not null,supplier_id uuid not null,received_at timestamptz not null,match_status text not null,invoice_total_cents bigint,loaded_at timestamptz not null default now());
create table public.analytics_fact_supplier_issues(issue_id uuid primary key,organization_id uuid not null,store_id uuid not null,supplier_id uuid not null,issue_type text not null,status text not null,created_at timestamptz not null,loaded_at timestamptz not null default now());
do $$ declare t text;begin foreach t in array array['analytics_dim_suppliers','analytics_dim_procurement_categories','analytics_fact_purchase_orders','analytics_fact_purchase_items','analytics_fact_supplier_quotes','analytics_fact_receivings','analytics_fact_supplier_issues'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,sensitive,allowed_dimensions) values
('purchase_spend','Purchase Spend','Gasto de compras concluídas.','sum(total_cents)','analytics_fact_purchase_orders','pedido de compra','Compras','15 min','cents','calculation',true,array['date','store','supplier']),
('supplier_on_time_rate','Supplier On-Time Rate','Entregas recebidas até a data prometida.','on_time / completed_receipts','analytics_fact_purchase_orders','fornecedor','Compras','daily','percent','calculation',false,array['date','store','supplier']),
('supplier_fill_rate','Fill Rate','Quantidade recebida sobre quantidade pedida.','received_quantity / quantity','analytics_fact_purchase_items','fornecedor/item','Compras','daily','percent','calculation',false,array['date','store','supplier']),
('purchase_price_variance','Price Variance','Variação entre preço pedido e recebido/faturado.','actual_price - ordered_price','purchase_order_items + purchase_receipt_items','item','Compras','daily','cents','calculation',true,array['date','store','supplier','item']),
('purchase_cycle_time','Purchase Cycle Time','Tempo entre criação e recebimento.','received_at - created_at','analytics_fact_purchase_orders','pedido de compra','Compras','daily','days','calculation',false,array['date','store','supplier']),
('stockout_risk','Stockout Risk','Itens com risco alto ou crítico de ruptura.','count(recommendations where stockout_risk in high,critical)','procurement_recommendations','item/unidade','Operações','15 min','count','calculation',false,array['date','store','item']),
('days_of_coverage','Days of Coverage','Estoque disponível dividido pelo consumo previsto diário.','available_stock / forecast_daily_consumption','procurement_recommendations','item/unidade','Operações','15 min','days','calculation',false,array['date','store','item']),
('supplier_concentration','Supplier Concentration','Participação do principal fornecedor no gasto da categoria.','max(supplier_spend) / category_spend','analytics_fact_purchase_orders','categoria','Compras','daily','percent','calculation',true,array['date','store','supplier']) on conflict(metric_key) do nothing;
insert into public.analytics_datasets(dataset_key,name,description,domain,owner_label,dataset_scope,grain,source_tables,refresh_frequency,retention_days,certified,contains_pii) values('procurement_mart','Procurement Mart','Pedidos, cotações, recebimentos, divergências e fornecedores.','procurement','Compras','customer_analytics','pedido/item/recebimento',array['purchase_orders','purchase_order_items','supplier_quotes','purchase_receipts','supplier_receiving_issues'],'15 min',2555,true,false) on conflict(dataset_key) do nothing;

-- Authenticated users receive read-only grants governed by RLS. Server routes own writes.
-- Sending, high-value approval, bank-data changes and payments remain explicit human actions.
